INSERT INTO public."Generation"(
	generationid, name, description)
	VALUES 
	(1, 'Generation 1', 'Originally introduced in Pokemon Red and Blue'),
	(2, 'Generation 2', 'With 100 new Pokémon, plus two new types added for balance, the Dark & Steel-types, Shiny Pokémon, genders, breeding and a whole new region'),
	(3, 'Generation 3', 'Adding a massive 135 Pokémon to the series, it changed things up with the addition of Double Battles, Abilities, Natures'),
	(4, 'Generation 4', 'It added 107 new Pokémon, including many evolutions of previous Pokémon and introduced online play'),
	(5, 'Generation 5', 'This generation acted, at first, as a soft reboot. In Black & White, you wouldnt see a single old Pokémon until after you have defeated the game'),
	(6, 'Generation 6', 'While having only 72 new Pokémon introduced, the games introduced a new feature called Mega Evolution, where 46 Pokémon could Mega Evolve in battle to their Mega Evolution'),
	(7, 'Generation 7', ' While it only introduced a slightly higher number of Pokémon to the last generation, the seventh generation continued the features of adapting old Pokémon, this time including regional variants of existing Pokémon.'),
	(8, 'Generation 8', ' Pokémon Sword & Shield were coming to the Nintendo Switch. This was the first time a generation would be available on a home console'),
	(9, 'Generation 9', 'Tsunekazu Ishihara and Takato Utsonomiya that revealed the next games, Pokémon Scarlet & Violet were coming to the Nintendo Switch.'),
	(10,'Generation 10', 'Pokémon Winds & Waves were coming to the Nintendo Switch 2.')
	;